import React from 'react';
import { Card, Form } from 'antd';
import { supplierFormConfig } from '../tests/testData';
import { DynamicForm } from '@/exports';
import { useDemoInitHandlers } from './useDemoInitHandlers';
import { useDemoSubmitResult } from './useDemoSubmitResult';
import OperatingAreaField from '../demos/customComponents/OperatingAreaField';

type StoreBoundaryFormValues = {
  [fieldName: string]: string | number | boolean | string[] | undefined;
};

const StoreBoundaryDemo: React.FC = () => {
  const { showSubmitResult, submitResultModal } = useDemoSubmitResult();

  const handleSubmit = (values: StoreBoundaryFormValues) => {
    console.log('[StoreBoundaryDemo] 表单提交:', values);
    showSubmitResult(values);
  };

  // 初始化处理器系统，确保所有演示组件都能正常工作
  useDemoInitHandlers();

  const [form] = Form.useForm();
  const currentValues = Form.useWatch([], { form, preserve: true }) ?? {};

  return (
    <div>
      <DynamicForm
        onSubmit={(values) => handleSubmit(values as StoreBoundaryFormValues)}
        form={form}
        submitButtonText="提交表单"
        formConfig={supplierFormConfig}
        componentRegistry={{ customComponents: { OperatingAreaField } }}
      />
      <Card title="当前 AntD Form values" style={{ marginTop: 16 }}>
        <pre style={{ margin: 0, whiteSpace: 'pre-wrap' }}>
          {JSON.stringify(currentValues, null, 2)}
        </pre>
      </Card>
      {submitResultModal}
    </div>
  );
};

export default StoreBoundaryDemo;

import { useInitHandlers } from '@/exports';
import type { InitConfig } from '@/consumer/effects';

const defaultDemoInitConfig: InitConfig = {
  enabled: true,
  handlers: [],
  options: { override: false },
  debug: true
};

export const useDemoInitHandlers = (config: Partial<InitConfig> = {}) => {
  return useInitHandlers({
    ...defaultDemoInitConfig,
    ...config,
    options: {
      ...defaultDemoInitConfig.options,
      ...config.options
    }
  });
};

import type { Chain } from '@whynotsnow/hooks';
import { GroupedFormConfig, FlatFormConfig } from '@/exports';
import { operatingAreaEffect } from '../demos/customComponents/OperatingAreaField';
export const supplierFormConfig: GroupedFormConfig = {
  groups: [
    {
      title: '企业信息',
      id: 'enterpriseInformation',
      fields: [
        {
          id: 'businessType',
          label: '供应商类型',
          component: 'SelectField',
          span: 8,
          componentProps: {
            options: [
              { value: 'manufacturer', label: '生鲜生产商' },
              { value: 'distributor', label: '生鲜经销商' },
              { value: 'wholesaler', label: '生鲜批发商' }
            ]
          },
          initialValue: 'manufacturer',
          dependents: ['industryType'],
          effect: (_changedValue: any, allValues: Record<string, any>, _chain: Chain) => {
            const businessType = allValues.businessType;
            const result = {
              groupsVisible: {
                businessInformation: businessType === 'manufacturer'
              }
            };
            return result;
          }
        },
        {
          id: 'employeeCount',
          label: '员工数量',
          component: 'NumberInput',
          span: 8,
          initialValue: 50,
          dependents: ['companySize']
        },
        {
          id: 'companySize',
          label: '企业规模',
          component: 'TextDisplay',
          span: 8,
          initialValue: (allValues: Record<string, any>) => {
            const employeeCount = allValues.employeeCount;
            if (employeeCount <= 50) {
              return '小型企业';
            } else if (employeeCount < 200) {
              return '中型企业';
            } else {
              return '大型企业';
            }
          },
          effect: (_changedValue: any, allValues: Record<string, any>, _chain: Chain) => {
            const employeeCount = allValues.employeeCount;
            let companySizeText = '';

            if (employeeCount <= 50) {
              companySizeText = '小型企业';
            } else if (employeeCount < 200) {
              companySizeText = '中型企业';
            } else {
              companySizeText = '大型企业';
            }

            return {
              value: companySizeText
            };
          }
        },
        {
          id: 'industryType',
          label: '生产行业',
          component: 'SelectField',
          span: 24,
          componentProps: {
            options: [
              { value: 'agriculturalPlanting', label: '种植业' },
              { value: 'aquaculture', label: '水产养殖' },
              { value: 'cookedFoodProcessing', label: '熟食加工' },
              { value: 'frozenFoodProcessing', label: '冷冻食品加工' }
            ]
          },

          initialValue: (allValues: Record<string, any>) => {
            const businessType = allValues.businessType;
            return {
              value: 'agriculturalPlanting',
              visible: businessType === 'manufacturer',
              disabled: businessType === 'distributor'
            };
          },
          effect: (_changedValue: any, allValues: Record<string, any>, _chain: Chain) => {
            const businessType = allValues.businessType;
            return { visible: businessType === 'manufacturer' };
          }
        }
      ]
    },
    {
      title: '生产经营信息',
      id: 'businessInformation',
      effect: (_changedValue: any, allValues: Record<string, any>, _chain: Chain) => {
        const businessType = allValues.businessType;
        return { visible: businessType === 'manufacturer' };
      },
      fields: [
        {
          id: 'operatingIncome',
          label: '年营收（万元）',
          span: 12,
          component: 'NumberInput',
          initialValue: () => {
            return {
              disabled: true,
              value: 3000
            };
          },
          effect: (val: any, allValues: Record<string, any>, _chain: Chain) => {
            const { profitRate } = allValues;
            const newValue = (profitRate * 3000) / 100;
            return {
              value: newValue,
              disabled: newValue > 5000
            };
          }
        },
        {
          id: 'profitRate',
          label: '营收完成率（%）',
          span: 12,
          component: 'NumberInput',
          initialValue: 100,
          dependents: ['operatingIncome']
        },
        {
          id: 'categories',
          label: '主营产品品类',
          component: 'SelectField',
          span: 12,
          dependents: ['operatingArea'],
          componentProps: {
            options: [
              { value: 'fruitsAndVegetables', label: '果蔬' },
              { value: 'aquatic', label: '水产' },
              { value: 'cookedFood', label: '熟食加工' },
              { value: 'Icecream/frozenProducts', label: '冷冻食品' }
            ]
          },

          initialValue: 'fruitsAndVegetables'
        },
        {
          id: 'operatingArea',
          label: '经营地区',
          component: 'OperatingAreaField',
          effect: operatingAreaEffect,
          span: 12,
          componentProps: {
            options: [
              { value: 'guangzhou', label: '广州' },
              { value: 'shenzhen', label: '深圳' },
              { value: 'shanghai', label: '上海' },
              { value: 'beijing', label: '北京' }
            ]
          },

          initialValue: (allValues: { categories: string }) => {
            const { categories } = allValues;
            let value = undefined;
            if (categories === 'fruitsAndVegetables') {
              value = 'guangzhou';
            }
            return {
              value
            };
          }
        }
      ]
    }
  ]
};

